from taf.ul.ettf.logger import custom_logger
from taf.ul.ettf.throughput.assertion_conditions import InvalidThroughputError
from taf.ul.ettf.sim.core.validators import Validators


logger = custom_logger('Command')


class CommandElements(object):
    def __init__(self):
        self._base = None
        self._params = {}
        self._modulators = {}

    @property
    def base(self):
        return self._base

    @property
    def params(self):
        return self._params

    @property
    def modulators(self):
        return self._modulators

    def add_base(self, base):
        self._base = base

    def add_param(self, option, value):
        self._params[option] = value

    def add_modulator(self, option, value):
        self._modulators[option] = value

    def get_param(self, option):
        return self._params.get(option, None)

    def get_modulator(self, option):
        return self._modulators.get(option, None)

    def default_assemble(self):
        return self._base + ''.join(' {}={}'.format(name, value) for name, value in sorted(self._params.items()))

    def clear(self):
        self.__init__()

    def extend_base(self, expression):
        self._base += ' {}'.format(expression)


class Assemblers(object):
    def __init__(self):
        self._assemblers = set()

    @property
    def assemblers(self):
        return self._assemblers

    def add_assembler(self, callback):
        self._assemblers.add(callback)

    def clear(self):
        self.__init__()

    def __iter__(self):
        return iter(self._assemblers)


class Command(object):
    command_elements = CommandElements()
    assemblers = Assemblers()

    def __init__(self, command, validators, parser=None):
        self._command = None
        self._validators = validators if validators else Validators()
        self._parser = parser

        self.clear()
        Command.command_elements.add_base(command)

    def run(self, simulator):
        try:
            self.assemble_command()
            return self._run(simulator)
        finally:
            self.clear()

    def add_param(self, option, value):
        self.command_elements.add_param(option, value)

    def update_param(self, option, value):
        self.command_elements.add_param(option, value)

    @staticmethod
    def clear():
        Command.assemblers.clear()
        Command.command_elements.clear()

    def _execute(self, simulator):
        logger.info('Executing simulator command: {}'.format(self.command))
        command_result = simulator.execute_command(self)
        logger.info('Simulator result:\n{}'.format(command_result))
        return self._validators.validate(self._parse(command_result))

    def _parse(self, command_result):
        return self._parser.parse(command_result) if self._parser else command_result

    def _run(self, simulator):
        retry = Command.command_elements.get_modulator('retry')
        retry = retry - 1 if retry else 0
        for _ in range(retry):
            try:
                return self._execute(simulator)
            except InvalidThroughputError as e:
                logger.error(e)
                raise
            except Exception as e:
                logger.warn('Execution failed: Egate connection refused')
                logger.warn(e)
        return self._execute(simulator)

    def replace_validators(self, *validators):
        self._validators = Validators(*validators)
        return self

    def add_validator(self, validator):
        self._validators.add(validator)

    def remove_validators(self):
        self._validators.clean()

    def with_parser(self, parser):
        self._parser = parser
        return self

    def extend_base(self, expression):
        self.command_elements.extend_base(expression)

    @property
    def command(self):
        return self._command

    @property
    def validators(self):
        return self._validators

    @property
    def parser(self):
        return self._parser

    def assemble_command(self):
        self.run_assemblers()
        self._command = Command.command_elements.default_assemble()

    @staticmethod
    def run_assemblers():
        for assembler in Command.assemblers:
            assembler()
